use semio_framework_value_clone_source_testing::FixtureSource;
use super::run_original_test_turn;
use semio_s_artifact_layout_layout_mutations_decisions::simple::SimpleAdvance;
use crate::LayoutMutation;
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use semio_s_artifact_layout_layout_mutations_decisions::override_decision::*;

use semio_framework_value::RetireOwned;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn source<T:RetireOwned+Sync+'static>(v:T)->FixtureSource<T>{FixtureSource::from_owner(v)}
fn close_source<T:RetireOwned+Sync+'static>(s:&mut FixtureSource<T>){while !s.terminal_is_empty(){s.close_once().unwrap();}}

#[test]
fn original_override_admission_and_partial_aliases_use_exact_caller_grants(){let fixture:serde_json::Value=serde_json::from_str(&crate::test_fixture_text("../../🧳️retained/📎️overrides/🧪️tests/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let event=decode::<LayoutMutation>(&row["mutation"]);let original=decode::<LayoutSnapshot>(&row["before"]);for cut in std::iter::once(usize::MAX).chain(fixture["cuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize)){let mut m=source(event.clone());let mut b=source(original.clone());let mut owner=OverrideDecision::default();let mut result=None;for turn in 0..cut{assert!(turn<100000);let d=owner.demand(m.borrow(),b.borrow(),256).unwrap();let g=grant(d);assert_eq!(run_original_test_turn(Default::default(),|step:&SimpleAdvance|step.progress,|effect,recover|{assert!(!recover);owner.advance(m.borrow(),b.borrow(),effect).map_err(Into::into)}).progress,Default::default());for short in[RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_depth:d.depth-1,..g}]{if short==g{continue}assert_eq!(run_original_test_turn(short,|step:&SimpleAdvance|step.progress,|effect,recover|{assert!(!recover);owner.advance(m.borrow(),b.borrow(),effect).map_err(Into::into)}).progress,Default::default())}let step=run_original_test_turn(g,|step:&SimpleAdvance|step.progress,|effect,recover|{assert!(!recover);owner.advance(m.borrow(),b.borrow(),effect).map_err(Into::into)});if step.done{result=Some(step);break}}if cut==usize::MAX{let step=result.expect("bounded original override progress");assert_eq!(step.error.is_none()&&!step.unchanged,row["accepted"].as_bool().unwrap());if let Some(error)=row["error"].as_str(){assert_eq!(step.error,Some(error))}let mut substituted=source(event.clone());assert!(owner.demand(substituted.borrow(),b.borrow(),256).is_err());close_source(&mut substituted)}owner.begin_close();for turn in 0..100000{if owner.terminal_is_empty(){break}assert!(turn<99999);let d=owner.close_demand(256).unwrap();assert_eq!(run_original_test_turn(Default::default(),RetainedCloneStep::progress,|effect,recover|{assert!(!recover);owner.close_step(256,effect).map_err(Into::into)}).progress(),Default::default());let step=run_original_test_turn(grant(d),RetainedCloneStep::progress,|effect,recover|{assert!(!recover);owner.close_step(256,effect).map_err(Into::into)});assert!(step.progress().fits(grant(d)))}assert_eq!(m.borrow().get(),&event);assert_eq!(b.borrow().get(),&original);close_source(&mut m);close_source(&mut b)}}}
